let colorSaturation = 0;

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  background("#f4efe4");

  // Clear the previous frame
  background(0);

  // Define color range
  const maxSaturation = 0.9; // Maximum saturation (rainbow)
  const minSaturation = 0.1;   // Minimum saturation (daylight)

  // Generate colors for each star
  let stars = [];
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const angle = map(x, 0, width, 0, TWO_PI);
      const saturation = minSaturation + ((maxSaturation - minSaturation) * cos(angle));
      if (saturation > maxSaturation) saturation = maxSaturation;
      stars.push({x, y, saturation});
    }
  }

  // Calculate a fixed height for the stars to center the patterns around it
  const maxHeight = stars.reduce((acc, star) => Math.max(acc, star.y), 0);

  for (const {x, y, saturation} of stars) {
    // Draw the fixed-height stars
    ellipse(x, y, 120, 120);
    // Place the median stars to make the gradient smoother
    if (y % maxHeight === maxHeight / 4) {
      ellipse(x + 120, y - 80, 80, 80);
      ellipse(x - 120, y + 80, 80, 80);
      ellipse(x + 120, y - 240, 80, 80);
      ellipse(x - 120, y + 240, 80, 80);
    }
    // Fill the star with the current gradient
    brush.fill(color("rgba(" + saturation + ", 0, 0, 1)");
  }

  // Draw the horizon lines for better visual separation
  line(width / 2, 0, width / 2, height);
  line(width / 2, height - 1, width / 2, 0);
}

