  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Add a Sunset effect using一条垂直的线
  let sunsetVertices = [];
  for (let i = 0; i < width; i++) {
    sunsetVertices.push({
      x: i,
      y: height,
      z: -100
    });
  }

  let currentVert = 0;
  let totalDistance = sunsetVertices.length * 400;

  while (totalDistance > 0) {
    let angle = Math.atan2(sunsetVertices[currentVert].y - sunsetVertices[currentVert + 1].y, sunsetVertices[currentVert].x - sunsetVertices[currentVert + 1].x);
    let distance = Math.sqrt(Math.pow(sunsetVertices[currentVert].x - sunsetVertices[currentVert + 1].x, 2) + Math.pow(sunsetVertices[currentVert].y - sunsetVertices[currentVert + 1].y, 2));

    if (distance < totalDistance) {
      sunsetVertices[currentVert] = {
        x: sunsetVertices[currentVert].x + (totalDistance - distance) * Math.cos(angle),
        y: sunsetVertices[currentVert].y + (totalDistance - distance) * Math.sin(angle),
        z: sunsetVertices[currentVert].z
      };
    } else {
      break;
    }

    currentVert++;
    totalDistance -= distance;
  }

  for (let vert of sunsetVertices) {
   Brush.line(vert.x, vert.y, vert.z);
  }

  // Add a green hill to the sky
  brush.noStroke();
  brush.fillTexture(0.5, 0.3);
  brush.fill("#0080ff", 180);
  brush.circle(200, 150, 60);
}

