  // Pattern for the sunset: it repeats every 4 cycles
  for (let i = 0; i < 4 * 360; i += 360) {
    let color = "#aeecff";

    if (i < 360 && i % 60 === 0) {
      color = "#ff438a";
    } else if (i < 720 && i % 60 === 0) {
      color = "#7e9ea1";
    }

    brush.beginShape(0.3);
    brush.vertex(0, 0);
    brush.vertex(400, 0);
    brush.vertex(400, 200);
    brush.vertex(0, 200);
    brush.endShape(true);
    brush.fill(color, 220);
    brush.circle(200, 150, 60);
  }
}

