function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Painting a sunset over the hills
  for (let i = 0; i < 360; i += 1) {
    let H = Math.sin(i * Math.PI / 180) * 100;
    let T = 0.5 + Math.sin(i * Math.PI / 180) * 50;

    brush.noStroke();
    brush.fillTexture(0.7, 0.5);
    brush.fill("#4c566a", 100);
    brush.beginShape(0.3);
    brush.vertex(200, H);
    brush.vertex(400, H);
    brush.vertex(400, 200 - T);
    brush.vertex(200, 200 - H);
    brush.endShape(true);
    brush.fill("#99a1bf", 50);
    brush.circle(200, 150 + H, 60);
  }

  // Adding a hint for a green clean side
  fill("#252F3A");
  strokeWeight(1);
  stroke("#FFFFFF");
  curve(0, 150);
  curve(200, 150);
  curve(400, 150);
  curve(200, 200);
  curve(0, 200);
  curve(400, 200);
}

