  brush.endShape(true);
  brush.fill("#9e69a4", 220);
  brush.circle(200, 150, 60);

  // Add a circular sunset
  let step = 40; // Distance between circles in x direction
  for (let i = 0; i < 10; i++) {
    circle(i * step, 300, 100); // Blue and red shells
  }

  // Add a horizon
  circle(400, 250, 100);

  // Add hills
  for (let i = 0; i < 10; i++) {
    const stepX = i * step; // Width of each hill in x direction
    circle(stepX, 0, 100);
    const height = 50 + i * 30; // Height of each hill in y direction
    brush.beginShape(0.3);
    brush.vertex(stepX, -height/2, 0);
    brush.vertex(stepX, -height/2, 200);
    brush.vertex(stepX, 0, 200);
    brush.endShape(true);
  }
}

