function sunRiseAndSet() {
  // Calculate the time when the sunset should begin
  var sunsetTime = (timeStamp - 2400000) % 86400; // 86400 seconds

  // Fill a gradient that transitions from sunset to full moon
  var x = 0.5;
  var y = sunsetTime;

  brush.noStroke();
  brush.beginShape(0.3);
  brush.vertex(x, y);
  brush.vertex(x + 1, y * 0.4);
  brush.vertex(x + 2, y * 0.4);
  brush.vertex(x + 3, y * 0.4);
  brush.vertex(x + 4, y * 0.4);
  brush.vertex(x, y * 1);
  brush.endShape(true);

  brush.fillTexture(0.5, 0.4);
  brush.beginShape(0.3);
  brush.vertex(x, y);
  brush.vertex(x + 1, y * 0.4);
  brush.vertex(x + 2, y * 0.4);
  brush.vertex(x + 3, y * 0.4);
  brush.vertex(x + 4, y * 0.4);
  brush.vertex(x, y * 1);
  brush.endShape(true);
}

